final class ContextRelationalModelMatrix {
 static int checks;static final int WORK=64000000;static void require(boolean b,String why){checks++;if(!b)throw new AssertionError(why);}
 static Snapshot bind(boolean x,String s)throws Exception{return ContextSignedUnaryModelMatrix.bind(x,s);}
 static ContextSignedModelEvaluation.Result evaluate(Snapshot x,List<Snapshot> fs){ContextSignedModelEvaluation.Result r=ContextSignedModelEvaluation.runAutomatic(x,fs,new ContextSignedModelRequest("!p(1);",Collections.emptyMap()).policy);require(r.status==ContextSignedModelInspection.Status.MODELLED_SUPPLIED&&r.relational!=null&&r.relational.output!=null,r.phase+": "+r.reason);ContextSignedRelationalModelAudit.check(r.relational.output,WORK);require(true,"fresh original AND all-final relational receipt audit");return r;}
 static void positive()throws Exception{
  for(int n:new int[]{0,2,9,64}){List<String> vars=ContextGeneralArgumentsMatrix.variables(n);Snapshot x=bind(true,ContextGeneralArgumentsMatrix.prefix(vars)+ContextGeneralArgumentsMatrix.atom("rel",vars)+";");ContextSignedModelEvaluation.Result r=evaluate(x,Collections.emptyList());require(r.relational.originalRows==1&&r.relational.output.ledger.models.get(Cut.of(x)).relations.containsKey(new Signature("rel",n)),"exact arbitrary signature and whole original row n="+n);require(r.relational.output.ledger.models.get(Cut.of(x)).relations.get(new Signature("rel",n)).otherwise,"all-admissible universal relation, no finite-domain truncation");}
  Snapshot nonuniform=bind(true,"!rel(1,2);!~rel(2,1);");ContextSignedModelEvaluation.Result r=evaluate(nonuniform,Collections.emptyList());ContextRelationalInterpretation m=r.relational.output.ledger.models.get(Cut.of(nonuniform));Table t=m.relations.get(new Signature("rel",2));require(t.holds(Arrays.asList(0,1),()->{})&&!t.holds(Arrays.asList(1,0),()->{}),"same relation depends on ordered tuple, not uniform predicate truth");require(t.holds(Arrays.asList(2,0),()->{})==t.otherwise&&t.holds(Arrays.asList(0,2),()->{})==t.otherwise,"outside class present in every coordinate");
  Snapshot typed=bind(true,"!rel(7,\"7\");!~rel(\"7\",7);");ContextSignedModelEvaluation.Result typedResult=evaluate(typed,Collections.emptyList());ContextRelationalInterpretation tm=typedResult.relational.output.ledger.models.get(Cut.of(typed));require(tm.points.size()==2&&tm.relations.get(new Signature("rel",2)).holds(Arrays.asList(0,1),()->{})&&!tm.relations.get(new Signature("rel",2)).holds(Arrays.asList(1,0),()->{}),"typed string7 and number7 are distinct model coordinates");
  Snapshot diagonal=bind(true,"!@u rel(u,u);!~rel(1,2);");r=evaluate(diagonal,Collections.emptyList());m=r.relational.output.ledger.models.get(Cut.of(diagonal));t=m.relations.get(new Signature("rel",2));require(t.holds(Arrays.asList(0,0),()->{})&&t.holds(Arrays.asList(1,1),()->{})&&t.holds(Arrays.asList(2,2),()->{})&&!t.holds(Arrays.asList(0,1),()->{}),"repeated variable diagonal includes outside class but does not force off-diagonal truth");
  Snapshot arities=bind(true,"!rel(1);!~rel(1,1);");r=evaluate(arities,Collections.emptyList());require(r.relational.output.ledger.models.get(Cut.of(arities)).relations.size()==2,"equal name with arities1 and2 are different signatures");
  List<String> one=new ArrayList<>(Collections.nCopies(64,"1")),two=new ArrayList<>(Collections.nCopies(64,"2"));Snapshot bounded=bind(true,"!"+ContextGeneralArgumentsMatrix.atom("wide",one)+";!~"+ContextGeneralArgumentsMatrix.atom("wide",two)+";");ContextSignedModelEvaluation.Result incomplete=ContextSignedModelEvaluation.runAutomatic(bounded,Collections.emptyList(),new ContextSignedModelRequest("!p(1);",Collections.emptyMap()).policy);require(incomplete.status==ContextSignedModelInspection.Status.MODELLED_SUPPLIED&&incomplete.relational!=null&&incomplete.relational.output.ledger.models.get(Cut.of(bounded)).relations.get(new Signature("wide",64)).exceptions.size()==1,"64-argument opposite ground tuples use one sparse exception, not an exponential table");
  ContextSignedModelEvaluation.Result sparse=incomplete;ContextSignedRelationalModelSearch.Data data=new ContextSignedRelationalModelSearch.Data(Cut.of(bounded));data.signatures.add(new Signature("wide",64));Method choices=ContextSignedRelationalModelSearch.class.getDeclaredMethod("choices",List.class,List.class,boolean.class,ContextSignedUnaryModelSearch.Policy.class,Runnable.class);choices.setAccessible(true);boolean allocationStopped=false;try{choices.invoke(null,Collections.singletonList(data),sparse.relational.output.ledger.models.get(Cut.of(bounded)).points,true,sparse.relational.output.ledger.policy,ContextGroundProductionRounds.budget(WORK));}catch(InvocationTargetException ex){if(!(ex.getCause() instanceof IllegalStateException))throw ex;allocationStopped=ex.getCause().getMessage().contains("BEFORE allocation");}require(allocationStopped,"dense Cartesian allocation independently refuses before allocation; sparse search remains usable");
  List<String> repeated64=new ArrayList<>(Collections.nCopies(64,"u")),offDiagonal=new ArrayList<>(Collections.nCopies(64,"1"));offDiagonal.set(63,"2");Snapshot irreflexive=bind(true,"!@u ~"+ContextGeneralArgumentsMatrix.atom("wide",repeated64)+";!"+ContextGeneralArgumentsMatrix.atom("wide",offDiagonal)+";");ContextSignedModelEvaluation.Result sparseFalse=evaluate(irreflexive,Collections.emptyList());Table falseDefault=sparseFalse.relational.output.ledger.models.get(Cut.of(irreflexive)).relations.get(new Signature("wide",64));require(!falseDefault.otherwise&&falseDefault.exceptions.size()==1,"false-default sparse candidate satisfies64-place irreflexive constraint plus positive off-diagonal tuple");
  List<String> constants=ContextGeneralArgumentsMatrix.values(64);Snapshot many=bind(true,"!"+ContextGeneralArgumentsMatrix.atom("wide",constants)+";");ContextSignedModelEvaluation.Result wide=ContextSignedModelEvaluation.runAutomatic(many,Collections.emptyList(),new ContextSignedModelRequest("!p(1);",Collections.singletonMap("points",64)).policy);require(wide.status==ContextSignedModelInspection.Status.MODELLED_SUPPLIED&&wide.relational!=null&&wide.namedPoints==64,"64 distinct ordinary constants with configured point budget, no hidden16-value ceiling");ContextSignedRelationalModelAudit.check(wide.relational.output,WORK);require(true,"wide constant tuple both independent audits");
  System.out.println("RELATIONAL_MODEL_POSITIVE arbitraryArity=0,2,9,64 orderedNonuniform=true repeatedOutsideDiagonal=true exactSignatures=true cartesianAllocationGuard=true");
 }
 static Ledger ledger(ContextSignedWitnessNativeBranch.Receipt b,Map<Cut,ContextRelationalInterpretation> models){List<Row> rows=new ArrayList<>();List<Snapshot> cuts=new ArrayList<>();cuts.add(b.x);cuts.addAll(b.foreign);for(Snapshot c:cuts)for(Snapshot member:c.physicalMembers())for(org.kanger.ContextProductionNativeBinding.Entry e:member.primary)rows.add(new Row(c,member,e));ContextSignedUnaryModelSearch.Policy p=new ContextSignedModelRequest("!p(1);",Collections.emptyMap()).policy.model.search;return new Ledger(b,p,models,rows,ContextSignedRelationalModelSearch.obligations(b,p,ContextGroundProductionRounds.budget(WORK)));}
 static ContextSignedWitnessNativeBranch.Receipt branch(Snapshot x){ContextSignedWitnessNativeBranch.Result b=ContextSignedWitnessNativeBranch.run(x,Collections.emptyList(),ContextSignedWitnessNativeMatrix.policy());require(b.output!=null,b.phase+": "+b.reason);return b.output;}
 static ContextRelationalInterpretation interpretation(Table table)throws Exception{return new ContextRelationalInterpretation(Collections.singletonList(ContextSignedUnaryModelMatrix.one()),Collections.singletonMap(new Signature("rel",2),table),Collections.emptyMap(),Collections.emptyMap());}
 static boolean originalAccepts(Ledger l){try{ContextSignedRelationalModelAudit.original(l,WORK);return true;}catch(IllegalStateException ex){return false;}}
 static void integrity()throws Exception{
  Snapshot all=bind(true,"!@u @v rel(u,v);"),diag=bind(true,"!@u rel(u,u);");ContextSignedWitnessNativeBranch.Receipt full=branch(all),repeated=branch(diag);Method finalTruth=ContextSignedRelationalModelAudit.class.getDeclaredMethod("finalTruth",Obligation.class,ContextRelationalInterpretation.class,Runnable.class);finalTruth.setAccessible(true);
  ContextSignedModelEvaluation.Result good=evaluate(all,Collections.emptyList());Obligation actual=good.relational.output.ledger.obligations.stream().filter(o->o.kind==Kind.UNIT).findFirst().get();
  for(int mask=0;mask<16;mask++){Map<List<Integer>,Boolean> entries=new LinkedHashMap<>();for(int x=0;x<2;x++)for(int y=0;y<2;y++)if((mask&(1<<(x*2+y)))!=0)entries.put(Arrays.asList(x,y),true);ContextRelationalInterpretation m=interpretation(new Table(false,entries));boolean whole=mask==15,diagonal=(mask&9)==9;require(originalAccepts(ledger(full,Collections.singletonMap(Cut.of(all),m)))==whole,"original Cartesian two-coordinate oracle mask="+mask);require(originalAccepts(ledger(repeated,Collections.singletonMap(Cut.of(diag),m)))==diagonal,"same-variable correlation oracle mask="+mask);boolean finalAccepted=true;try{finalTruth.invoke(null,actual,m,(Runnable)()->{});}catch(InvocationTargetException ex){if(!(ex.getCause() instanceof IllegalStateException))throw ex;finalAccepted=false;}require(finalAccepted==whole,"independent actual-final evaluator Cartesian oracle mask="+mask);}
  Ledger valid=good.relational.output.ledger;List<Obligation> missing=new ArrayList<>(valid.obligations);missing.remove(missing.size()-1);Ledger forged=new Ledger(valid.branch,valid.policy,valid.models,valid.rows,missing);ContextSignedRelationalModelAudit.OriginalReceipt initial=ContextSignedRelationalModelAudit.original(forged,WORK);boolean rejected=false;try{ContextSignedRelationalModelAudit.finalModel(forged,initial,WORK);}catch(IllegalStateException ex){rejected=true;}require(rejected,"genuine original model cannot hide a missing ACTUAL final carrier/Source alternative");
  ContextSignedUnaryModelSearch.Policy oldPolicy=valid.policy;ContextSignedUnaryModelSearch.Policy zeroCells=new ContextSignedUnaryModelSearch.Policy(oldPolicy.candidates,0,oldPolicy.witnesses,oldPolicy.work,oldPolicy.original,oldPolicy.extension);require(!originalAccepts(new Ledger(valid.branch,zeroCells,valid.models,valid.rows,valid.obligations)),"uniform table cannot bypass independently audited zero-cell model budget");
  rejected=false;try{ContextSignedRelationalModelAudit.finalModel(forged,good.relational.output.original,WORK);}catch(IllegalStateException ex){rejected=true;}require(rejected,"receipt for another ledger cannot substitute exact original model binding");
  Snapshot conditional=bind(true,"!@u p(u)->rel(u,u);");ContextSignedWitnessNativeBranch.Receipt cb=branch(conditional);Map<Signature,Table> bad=new LinkedHashMap<>();bad.put(new Signature("p",1),new Table(false,Collections.emptyMap()));bad.put(new Signature("rel",2),new Table(false,Collections.singletonMap(Collections.singletonList(0),true)));ContextRelationalInterpretation malformed=new ContextRelationalInterpretation(Collections.singletonList(ContextSignedUnaryModelMatrix.one()),bad,Collections.emptyMap(),Collections.emptyMap());require(!originalAccepts(ledger(cb,Collections.singletonMap(Cut.of(conditional),malformed))),"whole shape preflight rejects malformed later tuple despite uniformly true negative body");
  List<Integer> key=new ArrayList<>(Arrays.asList(0,1));Map<List<Integer>,Boolean> caller=new LinkedHashMap<>();caller.put(key,true);Table copied=new Table(false,caller);key.set(0,1);caller.clear();require(copied.holds(Arrays.asList(0,1),()->{})&&!copied.holds(Arrays.asList(1,1),()->{}),"sparse tuples deep copied from mutable caller data");
  System.out.println("RELATIONAL_MODEL_INTEGRITY truthOracles=48 actualFinalCarrier=true allOtherAndCorrelation=true noLostFinalProof=true exactReceiptBinding=true wholeShapeBeforeTruth=true copiedTuples=true");
 }
 static void topology()throws Exception{
  Snapshot x=bind(true,"!anchor(1);"),a=bind(false,"!rel(1,2);"),b=bind(false,"!~rel(1,2);");for(boolean reverse:new boolean[]{false,true}){List<Snapshot> fs=reverse?Arrays.asList(b,a):Arrays.asList(a,b);ContextSignedModelEvaluation.Result r=evaluate(x,fs);ContextRelationalInterpretation ma=r.relational.output.ledger.models.get(Cut.of(a)),mb=r.relational.output.ledger.models.get(Cut.of(b));require(ma.relations.get(new Signature("rel",2)).holds(Arrays.asList(0,1),()->{})&&!mb.relations.get(new Signature("rel",2)).holds(Arrays.asList(0,1),()->{}),"independent A-X/B-X retain opposite tuple truth, not shared communal table");}
  Snapshot trust=ContextProductionNativeBinding.trusted("relational",Arrays.asList(a,b),WORK);ContextSignedModelEvaluation.Result no=ContextSignedModelEvaluation.runAutomatic(x,Collections.singletonList(trust),new ContextSignedModelRequest("!p(1);",Collections.emptyMap()).policy);require(no.status==ContextSignedModelInspection.Status.REFUTED&&no.relational==null,"all physical TRUST rows refuted before model search");
  Snapshot witness=bind(true,"!$u rel(u,1)&&~rel(1,u);");ContextSignedModelEvaluation.Result growth=evaluate(witness,Collections.emptyList());require(growth.basisAttempts==2&&growth.namedPoints==2,"correlated tuple witness needs a second genuine value; failed small basis is not refutation");ContextRelationalInterpretation wm=growth.relational.output.ledger.models.get(Cut.of(witness));require(wm.witnesses.size()==1&&wm.witnesses.values().iterator().next()==1,"same Source-owned binder uses one value across positive/negative tuple positions");
  Snapshot coincident=bind(true,"!$u rel(u,u);!$v other(v,v);");ContextSignedModelEvaluation.Result same=evaluate(coincident,Collections.emptyList());ContextRelationalInterpretation cm=same.relational.output.ledger.models.get(Cut.of(coincident));require(cm.witnesses.size()==2&&cm.witnesses.values().stream().allMatch(v->v==0),"two distinct Source Origins may coincide in ONE concrete value");
  System.out.println("RELATIONAL_MODEL_TOPOLOGY independentOrders=2 separateTupleModels=true trustWholeRows=true correlatedWitnessBasisGrowth=true noForcedOriginInequality=true");
 }
}
